{
  "findings": [
    {
      "ref": "[D544]",
      "area": "contact",
      "claim": "A parent reports that users under 13 can no longer directly message others outside of games or experiences.",
      "stance": "risk",
      "quote": "users under the age of 13 will no longer able to directly message others on Roblox outside of games or experiences (also known as platform chat)"
    },
    {
      "ref": "[D544]",
      "area": "contact",
      "claim": "A parent reports that under‑13 users can only communicate via broadcast public chat and need parental consent for direct messaging within experiences.",
      "stance": "risk",
      "quote": "When communicating in a game or experience, users under the age of 13 will be able to communicate using the broadcast public chat. To use direct messaging within experiences, users under 13 will need parental consent."
    },
    {
      "ref": "[D544]",
      "area": "contact",
      "claim": "A parent reports that the legacy chat system and user‑to‑user inbox messaging have been removed.",
      "stance": "risk",
      "quote": "we’ve [removed] the ability for users to message each other via the Roblox Inbox and are removing the legacy chat system by April 30"
    },
    {
      "ref": "[D544]",
      "area": "money",
      "claim": "A parent reports that the platform no longer offers a parent PIN for account security.",
      "stance": "neutral",
      "quote": "As previously announced over email, as of today, you are no longer able to set or use a parent PIN on your Roblox account."
    },
    {
      "ref": "[D544]",
      "area": "data",
      "claim": "A parent reports that the platform may collect personal data for verification, including credit‑card information.",
      "stance": "risk",
      "quote": "why is credit card a option? Yall sure this is best decision, to allow anyone to verify with credit card, to be consider a adult."
    },
    {
      "ref": "[D544]",
      "area": "age_gating",
      "claim": "A parent reports that the age‑gate for users under 13 is enforced by filtering out experiences without content‑maturity labels from search and recommendations.",
      "stance": "mitigation",
      "quote": "All experiences without content maturity labels will be filtered out of search and any public or recommended sorts for users under 13."
    },
    {
      "ref": "[D544]",
      "area": "content",
      "claim": "A parent reports that experiences with social hangouts and free‑form user creation are restricted to users aged 13 and older.",
      "stance": "risk",
      "quote": "experiences with certain types of interactive features, specifically social hangouts and free-form 2D user creation, will only be accessible to users over the age of 13."
    },
    {
      "ref": "[D544]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory scrutiny and fines for data‑privacy and child‑safety concerns.",
      "stance": "risk",
      "quote": "Roblox is finally stepping into the right direction."
    }
  ]
}
